<script setup lang="ts">import { ref } from 'vue';const demoMode=import.meta.env.DEV;const demoMerchantName=demoMode?'大阪サンプル民泊清掃':'';const message=ref('');const messages=ref(demoMode?['お問い合わせありがとうございます。どのような清掃をご希望ですか？']:[]);function send():void{if(demoMode&&message.value.trim()){messages.value.push(message.value);message.value='';}}</script><template><section class="simple-page"><span class="eyebrow">MESSAGES</span><h1>問い合わせ</h1><div v-if="demoMode" class="chat-shell"><aside><b>{{ demoMerchantName }}</b><small>最新のメッセージがあります</small></aside><div class="chat-panel"><div class="chat-title"><b>{{ demoMerchantName }}</b><span class="open">オンライン</span></div><div class="messages"><p v-for="(item,index) in messages" :key="index" :class="{mine:index>0}">{{ item }}</p></div><form @submit.prevent="send"><input v-model="message" placeholder="メッセージを入力"><button>送信</button></form></div></div><div v-else class="empty"><b>問い合わせはまだありません</b><p>店舗ページから問い合わせると、こちらで確認できます。</p></div></section></template>
